  (21, 'Palomar College', '33826', 38843467865, '{"blocks":[{"courses":[{"alternatives":[],"catalog_addition":false,"code":"SPAN 101","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"SPAN 102","units":5,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"SPAN 211","units":5}],"catalog_addition":false,"code":"SPAN 201","units":5,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"SPAN 212","units":5}],"catalog_addition":false,"code":"SPAN 202","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"SPAN 235","units":3,"units_max":null}],"minimum":null,"name":"Program Requirements","option_group":null,"rule":"all","stated":{"max":23,"min":21}}],"program":{"careers":[],"degree_elective_units":{"max":null,"min":null},"degree_total":{"max":null,"min":null},"electives_fill_degree":false,"ge_pattern":"Cal-GETC","ge_units":{"max":null,"min":null},"measure":"units","open_elective_units":null,"outcomes":["Writing – Upon successful completion of this program, students will be able to write clear detailed text on a range of subjects passing on information or giving reasons in support of or against a particular point of view. Students will be able to write letters, essays or reports highlighting the personal significance of events and experiences and compare and contrast their own culture with that of the Spanish speaking world.","Listening – Upon successful completion of the program, students will be able to understand the main points of standard speech and follow some complex lines of argument. Students will be able to understand the main points of radio, TV programs and film that address current affairs or topics of personal and professional interest. Students will be able to recognize the linguistic variations that exist within the Spanish speaking world.","Speaking – Upon successful completion of the program, students will be able to interact with a degree of fluency and spontaneity that makes interaction with native speakers possible. Students will be able to take an active part in discussions on familiar topics. Students will be able to present facts and opinions, compare and contrast cultural differences, explain a viewpoint on a topical issue and argue the advantages and disadvantages of various options.","Reading – Upon successful completion of the program, students will be able to comprehend written materials such as articles, reports and simple literary texts that address contemporary issues of the Spanish speaking world. Students will be able to identify and evaluate the writers’ particular attitudes and viewpoints."],"section_heading":"World Languages  Department - Spanish - AA-T Transfer Major (18 units or more)","total_units":{"max":23,"min":21}}}'::jsonb, '{"arithmetic":"unequal","coverage":true,"invented":true,"listed":34,"placed":7}'::jsonb, '{"arithmetic":"unequal","confidence":{"catalog_year":100,"course_list_match":21,"ge_pattern":null,"source":100,"unit_arithmetic":60},"coverage":true,"gaps":["lists_past_their_figure"],"invented":true,"listed":34,"placed":7}'::jsonb),
